Literal.Value:
'{
  "data": {
    "name": "dataset"
  },
  "width": "container",
  "height": "container",
  "transform": [
    {
      "filter": "isValid(datum[''Não realizada no horário (GWh)''])"
    },
    {
      "joinaggregate": [
        {
          "op": "sum",
          "field": "Não realizada no horário (GWh)",
          "as": "nr_h"
        },
        {
          "op": "sum",
          "field": "Geração no horário (GWh)",
          "as": "g_h"
        }
      ],
      "groupby": [
        "Hora"
      ]
    },
    {
      "calculate": "datum.nr_h / (datum.g_h + datum.nr_h)",
      "as": "pct_h"
    }
  ],
  "encoding": {
    "x": {
      "field": "Hora",
      "type": "ordinal",
      "title": "Hora do dia",
      "axis": {
        "labelAngle": 0,
        "labelExpr": "datum.value % 3 == 0 ? datum.value + ''h'' : ''''"
      }
    }
  },
  "layer": [
    {
      "mark": {
        "type": "bar",
        "width": {
          "band": 0.8
        }
      },
      "encoding": {
        "y": {
          "field": "Não realizada no horário (GWh)",
          "type": "quantitative",
          "aggregate": "sum",
          "title": "GWh cortados",
          "axis": {
            "format": ",.0f",
            "tickCount": 4
          }
        },
        "color": {
          "field": "Fonte",
          "type": "nominal",
          "scale": {
            "domain": [
              "Eólica",
              "Solar"
            ],
            "range": [
              "#252423",
              "#F2C811"
            ]
          },
          "legend": {
            "orient": "top",
            "direction": "horizontal",
            "title": null
          }
        },
        "order": {
          "field": "Fonte"
        },
        "tooltip": [
          {
            "field": "Hora",
            "title": "Hora"
          },
          {
            "field": "Fonte"
          },
          {
            "field": "Não realizada no horário (GWh)",
            "aggregate": "sum",
            "title": "GWh",
            "format": ",.0f"
          }
        ]
      }
    },
    {
      "transform": [
        {
          "aggregate": [
            {
              "op": "max",
              "field": "pct_h",
              "as": "pct"
            }
          ],
          "groupby": [
            "Hora"
          ]
        }
      ],
      "mark": {
        "type": "line",
        "color": "#C84720",
        "strokeWidth": 2,
        "point": {
          "color": "#C84720",
          "size": 18
        }
      },
      "encoding": {
        "y": {
          "field": "pct",
          "type": "quantitative",
          "title": "% cortado (linha)",
          "axis": {
            "format": ".0%",
            "orient": "right",
            "titleColor": "#C84720",
            "tickCount": 4,
            "grid": false
          }
        },
        "tooltip": [
          {
            "field": "Hora",
            "title": "Hora"
          },
          {
            "field": "pct",
            "title": "% cortado no horário",
            "format": ".1%"
          }
        ]
      }
    }
  ],
  "resolve": {
    "scale": {
      "y": "independent"
    }
  }
}'
